#!/usr/bin/env python3
"""Pin the TWRP manifest projects that follow branches.

AOSP projects in the TWRP minimal manifest sit on a release tag and never move, but the
TeamWin/LineageOS forks follow branches (android-14.1, ...) and change under us: vold moving
to keystore2-V4 once left TWRP unable to start. This writes a repo local manifest that pins
those projects to commits with <extend-project>. base-rev makes repo fail loudly if the TWRP
manifest later moves a project to another branch.

usage: twrp_sources_lock.py <merged manifest from `repo manifest`> <new lock> [<old lock>]
Prints what changed against the old lock as Markdown.
"""
import concurrent.futures
import re
import subprocess
import sys
import xml.etree.ElementTree as ET

merged, out = sys.argv[1:3]
old_path = sys.argv[3] if len(sys.argv) > 3 else None

root = ET.parse(merged).getroot()
remotes = {r.get('name'): r for r in root.iter('remote')}
default = root.find('default')
default = default.attrib if default is not None else {}


def immutable(rev):
    return re.fullmatch(r'[0-9a-f]{40}', rev) or rev.startswith('refs/tags/')


projects = []  # (path, name, branch, url)
for p in root.iter('project'):
    remote = remotes[p.get('remote') or default['remote']]
    rev = p.get('revision') or remote.get('revision') or default.get('revision', '')
    if immutable(rev):
        continue
    fetch = remote.get('fetch')
    # shortcut: relative fetch URLs ("..") are not resolved; the TWRP 14.1 manifest has none
    assert '://' in fetch, f'relative fetch URL for {p.get("name")}: {fetch}'
    projects.append((p.get('path') or p.get('name'), p.get('name'), rev, fetch.rstrip('/') + '/' + p.get('name')))


def resolve(project):
    _, _, rev, url = project
    if rev.startswith('refs/'):
        order = [rev + '^{}', rev]
    else:
        order = [f'refs/heads/{rev}', f'refs/tags/{rev}^{{}}', f'refs/tags/{rev}']
    ls = subprocess.run(['git', 'ls-remote', url, order[-1], order[0].removesuffix('^{}')],
                        capture_output=True, text=True, timeout=180, check=True).stdout
    found = {ref: sha for sha, ref in (line.split('\t') for line in ls.splitlines())}
    for ref in order:
        if ref in found:
            return found[ref]
    raise LookupError(f'{url} has no {rev}')


with concurrent.futures.ThreadPoolExecutor(16) as pool:
    shas = list(pool.map(resolve, projects))

lines = ['<?xml version="1.0" encoding="UTF-8"?>',
         '<!-- Pins the TWRP 14.1 manifest projects that follow branches. Generated by',
         '     .github/scripts/twrp_sources_lock.py; update it with the "Update TWRP sources"',
         '     workflow, not by hand. -->',
         '<manifest>']
new = {}
for (path, name, rev, url), sha in sorted(zip(projects, shas)):
    new[path] = (name, rev, sha, url)
    lines.append(f'  <extend-project name="{name}" path="{path}" base-rev="{rev}" revision="{sha}" upstream="{rev}" />')
lines.append('</manifest>')
open(out, 'w').write('\n'.join(lines) + '\n')

old = {}
if old_path:
    try:
        for e in ET.parse(old_path).getroot().iter('extend-project'):
            old[e.get('path')] = e.get('revision')
    except FileNotFoundError:
        pass


def link(url, a, b):
    return f'{url}/compare/{a}...{b}' if 'github.com' in url else f'{url}/+log/{a}..{b}'


changes = []
for path, (name, rev, sha, url) in new.items():
    if path not in old:
        changes.append(f'| `{path}` | {rev} | new | `{sha[:12]}` |')
    elif old[path] != sha:
        changes.append(f'| `{path}` | {rev} | `{old[path][:12]}` | [`{sha[:12]}`]({link(url, old[path], sha)}) |')
changes += [f'| `{path}` | | `{old[path][:12]}` | removed |' for path in old if path not in new]

print(f'### TWRP sources: {len(new)} projects follow a branch, {len(changes)} changed\n')
if changes:
    print('| Project | Branch | Pinned | Latest |\n|---|---|---|---|')
    print('\n'.join(changes))
else:
    print('Everything is already pinned to the latest commits.')
